import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line = br.readLine();if (line == null) return;int t = Integer.parseInt(line.trim());while (t-- > 0) {int n = Integer.parseInt(br.readLine().trim());long andA = -1L;StringTokenizer stA = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) {long val = Long.parseLong(stA.nextToken());if (i == 0) andA = val;else andA &= val;}long andB = -1L;StringTokenizer stB = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) {long val = Long.parseLong(stB.nextToken());if (i == 0) andB = val;else andB &= val;}System.out.println(andA & andB);}}}